test("allows invoking the TypeScript parser from a custom parser", () => {
  const output = prettier.format("expect(foo).toMatchInlineSnapshot();", {
    parser(text, parsers, options) {
      options.parser = "typescript";
      // Jest's inline snapshot parser passes options as the second argument.
      return parsers.typescript(text, options);
    },
  });
  expect(output).toBe("expect(foo).toMatchInlineSnapshot();\n");
});

